import React, { useEffect, useRef, useState } from "react";
import { useParams } from "react-router-dom";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";
import { fetchMeetingById, updateMeeting } from "./meetingsApi2";

import Page1 from "./letter2/Page1";
import Page2 from "./letter2/Page2";
import Page3 from "./letter2/Page3";
import Page4 from "./letter2/Page4";
import Page5 from "./letter2/Page5";
import Page6 from "./letter2/Page6";
import Page7 from "./letter2/Page7";
import Page8 from "./letter2/Page8";

function formatDate(date) {
  // dd/mm/yyyy

  const d = new Date(date);
  const day = d.getDate();
  const month = d.getMonth() + 1;
  const year = d.getFullYear();
  return `${day}/${month}/${year}`;
}

const ListApplication = () => {
  const { id } = useParams();
  const [meeting, setMeeting] = useState(null);
  const [loading, setLoading] = useState(false);

  const page1Ref = useRef();
  const page2Ref = useRef();
  const page3Ref = useRef();
  const page4Ref = useRef();
  const page5Ref = useRef();
  const page6Ref = useRef();
  const page7Ref = useRef();
  const page8Ref = useRef();

  useEffect(() => {
    const loadMeeting = async () => {
      const res = await fetchMeetingById(id);
      console.log(res);
      setMeeting(res.data);
    };

    loadMeeting();
  }, [id]);

  const sendEmail = async () => {
    setLoading(true);
    try {
      const data = meeting;
      data.sendDate = new Date().toISOString();

      const response = await updateMeeting(data);

      setMeeting(data);

      // 1. Email body ko template literal me define karein
      const emailBody = `પ્રતિ,                                                                                       તારીખ :- ${formatDate(data.date)}

શ્રી તાલુકા વિકાસ અધિકારી સાહેબ,

તાલુકા પંચાયત કચેરી - ${data.taluka}

જિલ્લો - ${data.district} 

ખાસ અગત્યનું PDF File Download કરી આપશ્રી સાહેબના વંચાણે લેવું`;

      // 2. Subject aur Body ko encode karein
      const subject = encodeURIComponent("અગત્યની PDF File");
      const encodedBody = encodeURIComponent(emailBody);

      // 3. Gmail Compose URL
      const gmailLink = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(data.officeEmail)}&su=${subject}&body=${encodedBody}`;

      const mailtoLink = `mailto:${encodeURIComponent(data.officeEmail)}?subject=${subject}&body=${encodedBody}`;

      // 4. Open Gmail Compose
      window.open(mailtoLink, "_blank");

      alert("Email date Saved successfully!");
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const downloadPDF = async () => {
    setLoading(true);

    const pdf = new jsPDF("p", "mm", "a4");

    const pages = [
      page1Ref,
      page2Ref,
      page3Ref,
      page4Ref,
      page5Ref,
      page6Ref,
      page7Ref,
      page8Ref,
    ];

    for (let i = 0; i < pages.length; i++) {
      const pageElement = pages[i].current;

      if (!pageElement) continue;

      if (i > 0) pdf.addPage();

      const canvas = await html2canvas(pageElement, {
        scale: 2, // perfect for clarity
        useCORS: true,
        backgroundColor: "#ffffff",
        width: 794,
        height: 1123,
      });

      const imgData = canvas.toDataURL("image/jpeg", 1.0);

      const imgWidth = 210;
      const imgHeight = 297;

      pdf.addImage(imgData, "JPEG", 0, 0, imgWidth, imgHeight);
    }

    pdf.save(`Yaadi Arji Letter - ${meeting?.taluka}.pdf`);

    setLoading(false);
  };

  if (!meeting) return <div className="p-6">Loading...</div>;

  return (
    <div className="p-6 bg-gray-100">
      <div className="flex justify-end mb-4">
        <button
          onClick={downloadPDF}
          className="px-4 py-2 bg-blue-600 text-white rounded"
          disabled={loading}
        >
          {loading ? "Downloading..." : "Download PDF"}
        </button>

        {meeting?.sendDate ? (
          <button
            className="px-4 py-2 bg-green-600 text-white rounded ml-2"
            onClick={sendEmail}
          >
            Sent {formatDate(meeting?.sendDate)}
          </button>
        ) : (
          <button
            onClick={sendEmail}
            className="px-4 py-2 bg-green-600 text-white rounded ml-2"
          >
            {loading ? "Sending..." : "Send Email"}
          </button>
        )}
      </div>

      <div className="space-y-6">
        <div ref={page1Ref}>
          <Page1 data={meeting} />
        </div>

        <div ref={page2Ref}>
          <Page2 data={meeting} />
        </div>

        <div ref={page3Ref}>
          <Page3 data={meeting} />
        </div>

        <div ref={page4Ref}>
          <Page4 data={meeting} />
        </div>

        <div ref={page5Ref}>
          <Page5 data={meeting} />
        </div>

        <div ref={page6Ref}>
          <Page6 data={meeting} />
        </div>

        <div ref={page7Ref}>
          <Page7 data={meeting} />
        </div>

        <div ref={page8Ref}>
          <Page8 data={meeting} />
        </div>
      </div>
    </div>
  );
};

export default ListApplication;
